const settings = {
  testDir: "./tests",
  timeout: 30000,
  retries: 0,
  use: {                       // an object inside the object
    headless: true,
    baseURL: "https://test-automation-banking.vercel.app",
  },
};

console.log(settings.testDir);
console.log(settings.use.baseURL);        // two levels down
console.log(JSON.stringify(settings, null, 2));

console.log(60_000 === 60000);        // true — identical
console.log(5_000, 30_000, 60_000);

const ms = 90_000;
console.log(`${ms} ms is ${ms / 1000} seconds`);

// Two exports, so the difference is visible.
// A file may have many *named* exports, but only one default.

const config = { timeout: 60_000, retries: 1 };
const NAMED = "any number of these are allowed";

console.log("default-ish value:", JSON.stringify(config));
console.log("named value:      ", NAMED);

// In a real .ts file these would be:
//   export default config;      <- one per file
//   export const NAMED = ...;   <- as many as you like

import { launch, login } from "../_shared/deno-helpers.ts";

const { browser, page } = await launch();
await login(page);

const t0 = Date.now();
await page.waitForTimeout(3000);       // sleep for 3s, unconditionally
console.log("waitForTimeout(3000) actually took:", Date.now() - t0, "ms");

const started = Date.now();
let message = "";

try {
  // 2s instead of the 30s default, so this cell doesn't take half a minute
  await page.getByText("No Such Panel Exists").waitFor({ timeout: 2000 });
} catch (err) {
  message = (err as Error).message;
}

console.log("waited:", Date.now() - started, "ms");
console.log("error first line:", message.split("\n")[0]);

const t1 = Date.now();
await page.getByText("Account Balance", { exact: true }).waitFor({ timeout: 30_000 });
console.log("30s deadline, actually took:", Date.now() - t1, "ms");

let strictMessage = "";
const t2 = Date.now();

try {
  // "Statements" appears twice on this dashboard — verified, not a guess
  await page.getByText("Statements", { exact: true }).click({ timeout: 4000 });
} catch (err) {
  strictMessage = (err as Error).message;
}

console.log("took:", Date.now() - t2, "ms");
console.log(strictMessage.split("\n").slice(0, 3).join(" | "));

## Changing the defaults

Settings live in the config, never in the script — so one edit covers every test, and running
against a slower environment doesn't mean touching a hundred files.

```ts
// playwright.config.ts
export default defineConfig({
  testDir: "./",
  timeout: 60_000,               // per test (was 30s)
  expect: { timeout: 8_000 },    // per assertion (was 5s)
});
```

`timeout` sits at the top level; the assertion budget is nested under `expect`. Putting
`timeout` inside `expect` by mistake changes the wrong thing and is easy to miss.

// What the two settings look like as plain data
const configShape = {
  testDir: "./",
  timeout: 60_000,
  expect: { timeout: 8_000 },
};
console.log(JSON.stringify(configShape, null, 2));

await browser.close();

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week3/generated/day1-timeouts.spec.ts", `// Week 3, Day 1 — how Playwright's timeouts actually behave.
//
// Every deadline below was measured against the live app, not read off a doc page.
// Note that these tests all PASS: each one proves a timeout happened, rather than
// being a test that times out. A suite full of deliberately-red tests teaches you
// to ignore red.
//
// Written by a cell in week3/day1_2.ipynb. Run it yourself:
//   npx playwright test week3/generated/day1-timeouts.spec.ts
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test.describe("Timeouts", () => {
  test("Step 1 — a locator that never matches waits, then explains itself", async ({ page }) => {
    await loginAs(page);

    const started = Date.now();
    let message = "";
    try {
      // 2s instead of the 30s default, so the lesson does not take half a minute.
      await page.getByText("No Such Panel Exists").waitFor({ timeout: 2000 });
    } catch (error) {
      message = (error as Error).message;
    }
    const elapsed = Date.now() - started;

    expect(message).toContain("Timeout");
    // It really did wait — it did not give up immediately.
    expect(elapsed).toBeGreaterThanOrEqual(1800);
    expect(elapsed).toBeLessThan(8000);
  });

  test("Step 2 — expect() carries its own, shorter deadline", async ({ page }) => {
    await loginAs(page);

    const started = Date.now();
    let failed = false;
    try {
      await expect(page.getByText("No Such Panel Exists")).toBeVisible({ timeout: 1500 });
    } catch {
      failed = true;
    }
    const elapsed = Date.now() - started;

    expect(failed).toBe(true);
    expect(elapsed).toBeGreaterThanOrEqual(1300);
    // The action default is 30s; expect's default is 5s. They are separate settings.
    expect(elapsed).toBeLessThan(6000);
  });

  test("Step 3 — a matching locator returns at once, deadline unused", async ({ page }) => {
    await loginAs(page);

    const started = Date.now();
    // Generous deadline, but the element is already there.
    await expect(page.getByText("Account Balance", { exact: true })).toBeVisible({ timeout: 30_000 });
    const elapsed = Date.now() - started;

    // A timeout is a limit, not a wait. This is the single most misunderstood point.
    expect(elapsed).toBeLessThan(3000);
  });

  test("Step 4 — an ambiguous locator fails fast, and not because of time", async ({ page }) => {
    await loginAs(page);

    let message = "";
    try {
      // "Statements" appears twice on this dashboard — verified.
      await page.getByText("Statements", { exact: true }).click({ timeout: 4000 });
    } catch (error) {
      message = (error as Error).message;
    }

    // Strict mode: two matches is your bug, so Playwright refuses rather than guessing.
    expect(message).toMatch(/strict mode violation|resolved to 2 elements/);
  });

  test("Step 5 — setTimeout raises the budget for one test only", async ({ page }) => {
    // Per-test override. Useful for one genuinely slow journey; better than
    // raising the global timeout and slowing every failure down.
    test.setTimeout(45_000);
    await loginAs(page);
    await expect(page.getByRole("button", { name: "LogOut" })).toBeVisible();
  });
});
`);

await runSpec("week3/generated/day1-timeouts.spec.ts");

// The shapes, as plain data. Nothing runs — this is what you would write.
const perAssertion = 'await expect(locator).toBeVisible({ timeout: 10_000 });';
const perTest      = 'test.setTimeout(60_000);       // first line inside the test';
const roughlyPer   = 'test.slow();                    // 3x the configured timeout';
const global       = '{ timeout: 60_000, expect: { timeout: 8_000 } }';

for (const [name, form] of Object.entries({ perAssertion, perTest, roughlyPer, global })) {
  console.log(`${name.padEnd(14)} ${form}`);
}
